import sys, json, time, random
import numpy as np

def main():
    T0 = 0.0
    LIMIT = 8.0
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    rng = random.Random(seed)
    d = json.loads(sys.stdin.read())
    n, K = d["n"], d["K"]
    w = [int(x) for x in d["weights"]]; v = [int(x) for x in d["values"]]
    caps = [int(x) for x in d["caps"]]

    def emit(a):
        sys.stdout.write(json.dumps(a) + "\n"); sys.stdout.flush()

    def knap(items, C, vals=None):
        # exact 0/1 knapsack, returns chosen list
        items = [i for i in items if w[i] <= C]
        if not items or C <= 0:
            return []
        dp = np.zeros(C + 1, dtype=np.int64)
        take = np.zeros((len(items), C + 1), dtype=bool)
        for k, i in enumerate(items):
            wi = w[i]; vi = v[i] if vals is None else vals[i]
            cand = dp[:C + 1 - wi] + vi
            t = cand > dp[wi:]
            take[k, wi:] = t
            dp[wi:] = np.where(t, cand, dp[wi:])
        c = C; res = []
        for k in range(len(items) - 1, -1, -1):
            if take[k, c]:
                res.append(items[k]); c -= w[items[k]]
        return res

    # surrogate relaxation: one knapsack of capacity sum(caps) -> upper bound + full DP table
    Ct = sum(caps)
    D = np.zeros((n + 1, Ct + 1), dtype=np.int32)
    for i in range(n):
        wi = w[i]
        D[i + 1] = D[i]
        if wi <= Ct:
            np.maximum(D[i + 1, wi:], D[i, :Ct + 1 - wi] + v[i], out=D[i + 1, wi:])
    UB = int(D[n, Ct])
    # initial: greedy by ratio
    order = sorted(range(n), key=lambda i: -v[i] / w[i])
    asg = [-1] * n
    load = [0] * K
    for i in order:
        best = -1; bs = None
        for b in range(K):
            r = caps[b] - load[b] - w[i]
            if r >= 0 and (bs is None or r < bs):
                bs = r; best = b
        if best >= 0:
            asg[i] = best; load[best] += w[i]

    # candidate filter by ratio
    acc = 0; crit = 0.0
    for i in order:
        acc += w[i]
        if acc > Ct:
            crit = v[i] / w[i]; break
    FR = float(sys.argv[2]) if len(sys.argv) > 2 else 0.75
    good = [v[i] / w[i] >= crit * FR for i in range(n)]
    for i in range(n):
        if asg[i] >= 0: good[i] = True

    def total(a):
        return sum(v[i] for i in range(n) if a[i] >= 0)

    def reopt(a, S, drop=0, noise=0.0):
        a = a[:]
        Sset = set(S)
        pool = [i for i in range(n) if (a[i] == -1 and good[i]) or a[i] in Sset]
        for i in pool:
            a[i] = -1
        if drop:
            forb = set(rng.sample(pool, min(drop, len(pool))))
            pool2 = [i for i in pool if i not in forb]
        else:
            pool2 = pool
        vals = None
        if noise > 0:
            vals = {i: v[i] * (1.0 + noise * (rng.random() - 0.5)) for i in pool2}
        order_s = list(S); rng.shuffle(order_s)
        rem = pool2[:]
        rng.shuffle(rem)
        for b in order_s:
            ch = knap(rem, caps[b], vals)
            cs = set(ch)
            for i in ch:
                a[i] = b
            rem = [i for i in rem if i not in cs]
        load = [0] * K
        for i in range(n):
            if a[i] >= 0: load[a[i]] += w[i]
        for i in order:
            if a[i] == -1:
                for b in range(K):
                    if load[b] + w[i] <= caps[b]:
                        a[i] = b; load[b] += w[i]; break
        return a

    def sample_set(target):
        # random item set of surrogate value >= target, weight <= Ct
        c = Ct; need = target; X = []
        for k in range(n, 0, -1):
            i = k - 1
            sk = D[k - 1, c] >= need
            tk = w[i] <= c and D[k - 1, c - w[i]] >= need - v[i]
            if sk and tk:
                take = rng.random() < 0.5
            else:
                take = tk
            if take:
                X.append(i); c -= w[i]; need -= v[i]
        return X

    def pack(X, tries):
        # try to split X into bins via sequential subset-sum (bigint bitsets)
        bestp = None; bestpv = -1
        for _ in range(tries):
            a = [-1] * n
            rem = X[:]
            bins = list(range(K)); rng.shuffle(bins)
            for b in bins:
                rng.shuffle(rem)
                C = caps[b]; mask = (1 << (C + 1)) - 1
                Bs = [1]; B = 1
                for i in rem:
                    B = (B | (B << w[i])) & mask
                    Bs.append(B)
                s_ = B.bit_length() - 1
                taken = set()
                for j in range(len(rem) - 1, -1, -1):
                    if not (Bs[j] >> s_) & 1:
                        taken.add(rem[j]); s_ -= w[rem[j]]
                for i in taken: a[i] = b
                rem = [i for i in rem if i not in taken]
                if not rem: break
            if not rem:
                return a, True
            load = [0] * K
            for i in range(n):
                if a[i] >= 0: load[a[i]] += w[i]
            for i in order:
                if a[i] == -1:
                    for b in range(K):
                        if load[b] + w[i] <= caps[b]:
                            a[i] = b; load[b] += w[i]; break
            tv = total(a)
            if tv > bestpv: bestp, bestpv = a, tv
        return bestp, False

    cur = reopt(asg, list(range(K)))
    curv = total(cur)
    best, bestv = cur[:], curv
    it = 0
    last_imp = 0
    while time.process_time() - T0 < LIMIT and bestv < UB:
        it += 1
        r = rng.random()
        s = 2 if r < 0.6 else (3 if r < 0.9 else 1)
        S = rng.sample(range(K), s)
        drop = rng.randint(0, 4)
        noise = 0.0 if rng.random() < 0.5 else 0.05
        na = reopt(cur, S, drop, noise)
        nv = total(na)
        if nv >= curv:
            cur, curv = na, nv
            if nv > bestv:
                best, bestv = na[:], nv; last_imp = it
        if it % 20 == 0 and bestv < UB:
            X = sample_set(rng.randint(bestv + 1, UB))
            pa, ok = pack(X, 5)
            pv = total(pa)
            if pv > bestv:
                best, bestv = pa[:], pv; last_imp = it
                cur, curv = pa[:], pv
        if it - last_imp > 300 and rng.random() < 0.01:
            cur, curv = best[:], bestv
    load = [0] * K
    for i in range(n):
        if best[i] >= 0: load[best[i]] += w[i]
    assert all(load[b] <= caps[b] for b in range(K))
    emit(best)

