import sys, json, time, random
import numpy as np

T0 = time.process_time()
TLIM = 8.5

def el():
    return time.process_time() - T0

def ks_dp(idx, W, V, cap):
    """exact 0/1 knapsack over items idx; returns (value, chosen list)"""
    if cap <= 0 or len(idx) == 0:
        return 0, []
    dp = np.zeros(cap + 1, dtype=np.int64)
    keep = np.zeros((len(idx), cap + 1), dtype=bool)
    for j, i in enumerate(idx):
        w = W[i]
        if w > cap:
            continue
        cand = dp[:cap + 1 - w] + V[i]
        m = cand > dp[w:]
        keep[j, w:] = m
        dp[w:] = np.where(m, cand, dp[w:])
    c = cap
    ch = []
    for j in range(len(idx) - 1, -1, -1):
        if keep[j, c]:
            ch.append(idx[j]); c -= W[idx[j]]
    return int(dp[cap]), ch

def upper_bound(W, V, caps):
    C = sum(caps)
    dp = np.zeros(C + 1, dtype=np.int64)
    for i in range(len(W)):
        w = W[i]
        if w > C: continue
        np.maximum(dp[w:], dp[:C + 1 - w] + V[i], out=dp[w:])
    return int(dp[C])

def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    rng = random.Random(seed)
    d = json.loads(sys.stdin.read())
