        it += 1
        r = rng.random()
        if r < 0.3:
            bs = [rng.randrange(K)]
        elif r < 0.85:
            bs = rng.sample(range(K), 2)
        else:
            bs = rng.sample(range(K), 3)
        new = cur[:]
        for b in bs:
