import sys, json, time, random
import numpy as np

T0 = 0.0
LIMIT = 8.6


def elapsed():
    return time.process_time() - T0


def knap(items, W, V, cap, rng=None):
    """Exact 0/1 knapsack over list of items; returns (value, chosen list)."""
    if cap <= 0 or not items:
        return 0, []
    items = [i for i in items if W[i] <= cap]
    if not items:
        return 0, []
    if rng is not None:
        rng.shuffle(items)
    m = len(items)
    dp = np.zeros(cap + 1, dtype=np.int64)
    keep = np.zeros((m, cap + 1), dtype=np.bool_)
    for k, i in enumerate(items):
        w = W[i]; v = V[i]
        cand = dp[:cap + 1 - w] + v
        mask = cand > dp[w:]
        keep[k, w:] = mask
        dp[w:] = np.where(mask, cand, dp[w:])
    c = cap
    ch = []
    for k in range(m - 1, -1, -1):
        if keep[k, c]:
            i = items[k]
            ch.append(i)
            c -= W[i]
    return int(dp[cap]), ch


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    rng = random.Random(seed)
    inst = json.loads(sys.stdin.read())
    n = inst["n"]; K = inst["K"]
    W = list(inst["weights"]); V = list(inst["values"]); caps = list(inst["caps"])

    assign = [-1] * n

    def total(a):
        return sum(V[i] for i in range(n) if a[i] >= 0)

    def emit(a):
        sys.stdout.write(json.dumps(a) + "\n")
        sys.stdout.flush()

    # quick greedy (safety answer)
    order = sorted(range(n), key=lambda i: -V[i] / W[i])
    load = [0] * K
    for i in order:
        for b in sorted(range(K), key=lambda b: caps[b] - load[b]):
            if load[b] + W[i] <= caps[b]:
                assign[i] = b; load[b] += W[i]; break
    best = assign[:]
    bestval = total(best)

    # sequential DP init
    a = [-1] * n
    for b in sorted(range(K), key=lambda b: caps[b]):
        pool = [i for i in range(n) if a[i] < 0]
        _, ch = knap(pool, W, V, caps[b])
        for i in ch:
            a[i] = b
    cur = a
    curval = total(cur)
    if curval > bestval:
        best, bestval = cur[:], curval

    # surrogate upper bound (all capacity in one)
    ub, _ = knap(list(range(n)), W, V, sum(caps))

    bins_val = [0] * K
    for i in range(n):
        if cur[i] >= 0:
            bins_val[cur[i]] += V[i]

    it = 0
    stag = 0
    while elapsed() < LIMIT and bestval < ub:
        it += 1
        r = rng.random()
        if r < 0.75:
            bs = rng.sample(range(K), 2)
        else:
            bs = rng.sample(range(K), 3)
        old = sum(bins_val[b] for b in bs)
        pool = [i for i in range(n) if cur[i] < 0 or cur[i] in bs]
        rng.shuffle(bs)
        newsets = []
        rem = set(pool)
        tot = 0
        for b in bs:
            v, ch = knap(list(rem), W, V, caps[b], rng)
            newsets.append((b, v, ch))
            tot += v
            rem.difference_update(ch)
        if tot >= old:
            for i in pool:
                cur[i] = -1
            for b, v, ch in newsets:
                bins_val[b] = v
                for i in ch:
                    cur[i] = b
            if tot > old:
                stag = 0
            curval = curval - old + tot
            if curval > bestval:
                best, bestval = cur[:], curval
        stag += 1
        if stag > 120:
            stag = 0
            # try to pack a (random) surrogate-optimal item set exactly
            for _ in range(3):
                if elapsed() > LIMIT - 0.3:
                    break
                sv, S = knap(list(range(n)), W, V, sum(caps), rng)
                bo = list(range(K)); rng.shuffle(bo)
                rem = set(S); a2 = [-1] * n
                for b in bo:
                    _, ch = knap(list(rem), W, W, caps[b], rng)
                    for i in ch:
                        a2[i] = b
                    rem.difference_update(ch)
                if not rem:
