                    break
            if bestval >= ub:
                break
            cur = best[:]
            taken = [i for i in range(n) if cur[i] >= 0]
            for i in rng.sample(taken, min(len(taken), rng.randint(3, 15))):
                cur[i] = -1
            bins_val = [0] * K
            for i in range(n):
                if cur[i] >= 0:
                    bins_val[cur[i]] += V[i]
            curval = sum(bins_val)
    # validate
    ld = [0] * K
    for i in range(n):
        if best[i] >= 0:
            ld[best[i]] += W[i]
    if not all(ld[b] <= caps[b] for b in range(K)):
        best = assign
    emit(best)
    sys.stderr.write("val %d ub %d gap %d it %d t %.2f\n" % (bestval, ub, ub - bestval, it, elapsed()))


